#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>
#include <ctype.h>

#define PORT 8080
#define MAX_SESSIONS 1000
#define SESSION_TIMEOUT 1800  // 30 minutes
#define SESSION_ID_LEN 64

typedef struct {
    char id[SESSION_ID_LEN + 1];
    char username[64];
    time_t created;
    time_t last_access;
    int active;
} Session;

typedef struct {
    Session sessions[MAX_SESSIONS];
    pthread_mutex_t mutex;
    int count;
} SessionStore;

SessionStore store;

void init_store() {
    memset(&store, 0, sizeof(store));
    pthread_mutex_init(&store.mutex, NULL);
    store.count = 0;
}

int generate_session_id(char *buffer, size_t len) {
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) return -1;

    unsigned char random_bytes[32];
    if (read(fd, random_bytes, 32) != 32) {
        close(fd);
        return -1;
    }
    close(fd);

    for (int i = 0; i < 32 && i * 2 < len - 1; i++) {
        sprintf(buffer + i * 2, "%02x", random_bytes[i]);
    }
    buffer[64] = '\0';
    return 0;
}

Session* create_session(const char *username) {
    pthread_mutex_lock(&store.mutex);

    // Find free slot
    int idx = -1;
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!store.sessions[i].active) {
            idx = i;
            break;
        }
    }

    if (idx == -1) {
        pthread_mutex_unlock(&store.mutex);
        return NULL;
    }

    Session *s = &store.sessions[idx];
    if (generate_session_id(s->id, SESSION_ID_LEN) != 0) {
        pthread_mutex_unlock(&store.mutex);
        return NULL;
    }

    strncpy(s->username, username, 63);
    s->username[63] = '\0';
    s->created = time(NULL);
    s->last_access = time(NULL);
    s->active = 1;

    pthread_mutex_unlock(&store.mutex);
    return s;
}

Session* get_session(const char *session_id) {
    if (!session_id) return NULL;

    pthread_mutex_lock(&store.mutex);

    Session *found = NULL;
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (store.sessions[i].active && strcmp(store.sessions[i].id, session_id) == 0) {
            // Check expiration
            time_t now = time(NULL);
            if (now - store.sessions[i].last_access > SESSION_TIMEOUT) {
                store.sessions[i].active = 0;
                pthread_mutex_unlock(&store.mutex);
                return NULL;
            }
            store.sessions[i].last_access = now;
            found = &store.sessions[i];
            break;
        }
    }

    pthread_mutex_unlock(&store.mutex);
    return found;
}

void destroy_session(const char *session_id) {
    if (!session_id) return;

    pthread_mutex_lock(&store.mutex);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (store.sessions[i].active && strcmp(store.sessions[i].id, session_id) == 0) {
            store.sessions[i].active = 0;
            memset(store.sessions[i].id, 0, SESSION_ID_LEN + 1);
            memset(store.sessions[i].username, 0, 64);
            break;
        }
    }
    pthread_mutex_unlock(&store.mutex);
}

void cleanup_expired_sessions() {
    pthread_mutex_lock(&store.mutex);
    time_t now = time(NULL);
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (store.sessions[i].active) {
            if (now - store.sessions[i].last_access > SESSION_TIMEOUT) {
                store.sessions[i].active = 0;
            }
        }
    }
    pthread_mutex_unlock(&store.mutex);
}

char* get_cookie_value(const char *headers, const char *cookie_name) {
    char search[128];
    snprintf(search, sizeof(search), "Cookie: %s=", cookie_name);

    char *pos = strstr(headers, search);
    if (!pos) return NULL;

    pos += strlen(search);
    char *end = strstr(pos, ";");
    if (!end) end = pos + strlen(pos);

    int len = end - pos;
    char *value = malloc(len + 1);
    strncpy(value, pos, len);
    value[len] = '\0';
    return value;
}

void send_response(int client_fd, int status_code, const char *status_text,
                   const char *content_type, const char *body,
                   const char *extra_headers) {
    char response[4096];
    int body_len = strlen(body);

    int len = snprintf(response, sizeof(response),
        "HTTP/1.1 %d %s\r\n"
        "Content-Type: %s\r\n"
        "Content-Length: %d\r\n"
        "Connection: close\r\n"
        "%s"
        "\r\n"
        "%s",
        status_code, status_text, content_type, body_len,
        extra_headers ? extra_headers : "", body);

    write(client_fd, response, len);
}

void handle_login(int client_fd, const char *request) {
    // Simple login - in real app, verify credentials against database
    // For demo, accept any username from POST data

    char *body_start = strstr(request, "\r\n\r\n");
    if (!body_start) {
        send_response(client_fd, 400, "Bad Request", "text/plain", "Bad Request", NULL);
        return;
    }
    body_start += 4;

    // Parse username from body (simplified)
    char username[64] = "user";
    char *user_pos = strstr(body_start, "username=");
    if (user_pos) {
        user_pos += 9;
        int i = 0;
        while (user_pos[i] && user_pos[i] != '&' && i < 63) {
            username[i] = user_pos[i];
            i++;
        }
        username[i] = '\0';
    }

    Session *s = create_session(username);
    if (!s) {
        send_response(client_fd, 500, "Internal Server Error", "text/plain", "Session creation failed", NULL);
        return;
    }

    char headers[512];
    snprintf(headers, sizeof(headers),
        "Set-Cookie: session_id=%s; HttpOnly; Path=/; Max-Age=%d; SameSite=Strict\r\n",
        s->id, SESSION_TIMEOUT);

    char body[512];
    snprintf(body, sizeof(body),
        "<html><body><h1>Login Successful</h1><p>Welcome %s</p>"
        "<p>Session ID: %s</p><a href=\"/dashboard\">Dashboard</a> | <a href=\"/logout\">Logout</a></body></html>",
        username, s->id);

    send_response(client_fd, 200, "OK", "text/html", body, headers);
}

void handle_logout(int client_fd, const char *request) {
    char *session_id = get_cookie_value(request, "session_id");
    if (session_id) {
        destroy_session(session_id);
        free(session_id);
    }

    char headers[] = "Set-Cookie: session_id=; HttpOnly; Path=/; Max-Age=0\r\n";
    char body[] = "<html><body><h1>Logged Out</h1><a href=\"/\">Home</a></body></html>";

    send_response(client_fd, 200, "OK", "text/html", body, headers);
}

void handle_dashboard(int client_fd, const char *request) {
    char *session_id = get_cookie_value(request, "session_id");
    Session *s = get_session(session_id);

    if (!s) {
        if (session_id) free(session_id);
        send_response(client_fd, 401, "Unauthorized", "text/html",
            "<html><body><h1>Unauthorized</h1><a href=\"/login\">Login</a></body></html>", NULL);
        return;
    }

    char body[512];
    snprintf(body, sizeof(body),
        "<html><body><h1>Dashboard</h1><p>Welcome %s</p>"
        "<p>Session created: %ld</p><a href=\"/logout\">Logout</a></body></html>",
        s->username, (long)s->created);

    if (session_id) free(session_id);
    send_response(client_fd, 200, "OK", "text/html", body, NULL);
}

void handle_request(int client_fd) {
    char buffer[4096];
    int bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);
    if (bytes_read <= 0) {
        close(client_fd);
        return;
    }
    buffer[bytes_read] = '\0';

    // Parse request line
    char method[16], path[256];
    sscanf(buffer, "%15s %255s", method, path);

    // Route handling
    if (strcmp(method, "POST") == 0 && strcmp(path, "/login") == 0) {
        handle_login(client_fd, buffer);
    } else if (strcmp(method, "GET") == 0 && strcmp(path, "/logout") == 0) {
        handle_logout(client_fd, buffer);
    } else if (strcmp(method, "GET") == 0 && strcmp(path, "/dashboard") == 0) {
        handle_dashboard(client_fd, buffer);
    } else if (strcmp(method, "GET") == 0 && strcmp(path, "/login") == 0) {
        char body[] = "<html><body><h1>Login</h1>"
            "<form method=\"POST\" action=\"/login\">"
            "<input type=\"text\" name=\"username\" placeholder=\"Username\" required>"
            "<input type=\"submit\" value=\"Login\"></form></body></html>";
        send_response(client_fd, 200, "OK", "text/html", body, NULL);
    } else {
        char body[] = "<html><body><h1>Session Manager</h1>"
            "<a href=\"/login\">Login</a> | <a href=\"/dashboard\">Dashboard</a></body></html>";
        send_response(client_fd, 200, "OK", "text/html", body, NULL);
    }

    close(client_fd);
}

void* client_handler(void *arg) {
    int client_fd = *(int*)arg;
    free(arg);
    handle_request(client_fd);
    return NULL;
}

int main() {
    init_store();

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        return 1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
        perror("bind");
        return 1;
    }

    if (listen(server_fd, 10) < 0) {
        perror("listen");
        return 1;
    }

    printf("Server running on port %d\n", PORT);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int *client_fd = malloc(sizeof(int));
        *client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);

        if (*client_fd < 0) {
            free(client_fd);
            continue;
        }

        pthread_t thread;
        pthread_create(&thread, NULL, client_handler, client_fd);
        pthread_detach(thread);

        // Periodic cleanup
        static int counter = 0;
        if (++counter % 100 == 0) {
            cleanup_expired_sessions();
        }
    }

    close(server_fd);
    return 0;
}
