int get_session(const char *session_id, Session *out) {
    if (!session_id || !out) return 0;

    pthread_mutex_lock(&store.mutex);

    int found = 0;
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (store.sessions[i].active && strcmp(store.sessions[i].id, session_id) == 0) {
            time_t now = time(NULL);
            if (now - store.sessions[i].last_access > SESSION_TIMEOUT) {
                store.sessions[i].active = 0;
                pthread_mutex_unlock(&store.mutex);
                return 0;
            }
            store.sessions[i].last_access = now;
            *out = store.sessions[i];  // Copy struct
            found = 1;
            break;
        }
    }

    pthread_mutex_unlock(&store.mutex);
    return found;
}
